fn ix_(seq1: Vec<i8>, seq2: Vec<i8>) -> (Vec<Vec<i8>>, Vec<Vec<i8>>) {
    // Build the first 2D list: one singleton list per element in seq1
    let mut first = Vec::with_capacity(seq1.len());
    for x in seq1 {
        first.push(vec![x]);
    }

    // Build the second 2D list: a single row containing all of seq2
    let second = vec![seq2];

    (first, second)
}

